    Matcher keySizeMatcher = keySizePattern.matcher(constraintEntry);
    if (keySizeMatcher.matches()) {
        String op = keySizeMatcher.group(1);
        int keySize = Integer.parseInt(keySizeMatcher.group(2));
        String keyAlgorithm = keySizeMatcher.group(0).split("\\s+")[0];
        addConstraint(keyAlgorithm, new KeySizeConstraint(op, keySize));
    }

    Matcher denyAfterMatcher = denyAfterPattern.matcher(constraintEntry);
    if (denyAfterMatcher.matches()) {
        String year = denyAfterMatcher.group(1);
        String month = denyAfterMatcher.group(2);
        String day = denyAfterMatcher.group(3);
        Date denyAfter = new SimpleDateFormat("yyyy-MM-dd").parse(year + "-" + month + "-" + day);
        String keyAlgorithm = denyAfterMatcher.group(0).split("\\s+")[0];
        addConstraint(keyAlgorithm, new DenyAfterConstraint(denyAfter));
    }
}

