class _SliceIterator(object):
    def __init__(self, cube, dims_index, dim_to_slice, ordered):
        self.cube = cube
        self.dims_index = dims_index
        self.dim_to_slice = dim_to_slice
        self.ordered = ordered
        self._index = 0
    def __iter__(self):
        return self
    def next(self):
        if self._index == len(self.cube.shape):
            raise StopIteration
        new_shape = [self.cube.shape[dim] for dim in range(len(self.cube.shape))]
        for dim in range(len(self.cube.shape)):
            if dim in self.dim_to_slice:
                new_shape[dim] = 1
        new_cube = self.cube[tuple([slice(None) if dim in self.dim_to_slice
                                    else self.dims_index[dim] for dim in
                                    range(len(self.cube.shape))])]
        if self.ordered:
            self._index += 1
        return new_cube
